/**
 * GroupBlock - Expandable, nestable group container
 */

import React, { useState, useCallback, useRef } from 'react';
import useStore from '../../store/useStore';
import { Edit2, Trash2, Copy, Palette } from 'lucide-react';
import './Blocks.css';

const buildGroupTree = (groups, rootId) => {
  const tree = [];
  const stack = [rootId];
  while (stack.length) {
    const current = stack.pop();
    tree.push(current);
    groups
      .filter((group) => group.parentId === current)
      .forEach((child) => stack.push(child.id));
  }
  return tree;
};

const GroupBlock = ({ group }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [name, setName] = useState(group.name);
  const [isResizing, setIsResizing] = useState(false);
  const startPosRef = useRef({ x: 0, y: 0, width: 0, height: 0 });
  const inputRef = useRef(null);
  const dragStateRef = useRef(null);

  const {
    updateGroup,
    updateTimetable,
    updateTeacherPlacement,
    updateSubjectPlacement,
    deleteGroup,
    selectElement,
    isSelected,
    showContextMenu,
  } = useStore();

  const selected = isSelected('group', group.id);

  // Handle dragging the group
  const handleMouseDown = useCallback((e) => {
    if (e.target.closest('.resize-handle') || isEditing) return;
    if (e.button !== 0) return;

    e.stopPropagation();
    selectElement('group', group.id, e.shiftKey);

    const startX = e.clientX;
    const startY = e.clientY;
    const state = useStore.getState();
    const groupTree = buildGroupTree(state.groups, group.id);
    const groupSet = new Set(groupTree);
    const initialPositions = {
      groups: {},
      timetables: {},
      teachers: {},
      subjects: {},
    };
    groupTree.forEach((groupId) => {
      const currentGroup = state.groups.find((g) => g.id === groupId);
      if (currentGroup) {
        initialPositions.groups[groupId] = { x: currentGroup.x, y: currentGroup.y };
      }
    });
    state.timetables.forEach((timetable) => {
      if (groupSet.has(timetable.groupId)) {
        initialPositions.timetables[timetable.id] = { x: timetable.x, y: timetable.y };
      }
    });
    state.teacherPlacements.forEach((placement) => {
      if (groupSet.has(placement.groupId)) {
        initialPositions.teachers[placement.id] = { x: placement.x, y: placement.y };
      }
    });
    state.subjectPlacements.forEach((placement) => {
      if (groupSet.has(placement.groupId)) {
        initialPositions.subjects[placement.id] = { x: placement.x, y: placement.y };
      }
    });
    dragStateRef.current = { startX, startY, groupTree, initialPositions };

    const handleMouseMove = (moveEvent) => {
      const dragState = dragStateRef.current;
      if (!dragState) return;
      const zoom = useStore.getState().canvas.zoom;
      const deltaX = (moveEvent.clientX - dragState.startX) / zoom;
      const deltaY = (moveEvent.clientY - dragState.startY) / zoom;

      dragState.groupTree.forEach((groupId) => {
        const initial = dragState.initialPositions.groups[groupId];
        if (initial) {
          updateGroup(groupId, { x: initial.x + deltaX, y: initial.y + deltaY });
        }
      });

      Object.entries(dragState.initialPositions.timetables).forEach(([id, position]) => {
        updateTimetable(id, { x: position.x + deltaX, y: position.y + deltaY });
      });

      Object.entries(dragState.initialPositions.teachers).forEach(([id, position]) => {
        updateTeacherPlacement(id, { x: position.x + deltaX, y: position.y + deltaY });
      });

      Object.entries(dragState.initialPositions.subjects).forEach(([id, position]) => {
        updateSubjectPlacement(id, { x: position.x + deltaX, y: position.y + deltaY });
      });
    };

    const handleMouseUp = () => {
      dragStateRef.current = null;
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
  }, [group.id, isEditing, selectElement, updateGroup, updateTimetable, updateTeacherPlacement, updateSubjectPlacement]);

  // Handle resizing
  const handleResizeStart = useCallback((e, handle) => {
    e.stopPropagation();
    e.preventDefault();
    
    setIsResizing(true);
    startPosRef.current = {
      x: e.clientX,
      y: e.clientY,
      width: group.width,
      height: group.height,
      groupX: group.x,
      groupY: group.y,
    };

    const handleMouseMove = (moveEvent) => {
      const zoom = useStore.getState().canvas.zoom;
      const deltaX = (moveEvent.clientX - startPosRef.current.x) / zoom;
      const deltaY = (moveEvent.clientY - startPosRef.current.y) / zoom;

      let updates = {};

      if (handle.includes('e')) {
        updates.width = Math.max(100, startPosRef.current.width + deltaX);
      }
      if (handle.includes('w')) {
        const newWidth = Math.max(100, startPosRef.current.width - deltaX);
        updates.width = newWidth;
        updates.x = startPosRef.current.groupX + (startPosRef.current.width - newWidth);
      }
      if (handle.includes('s')) {
        updates.height = Math.max(80, startPosRef.current.height + deltaY);
      }
      if (handle.includes('n')) {
        const newHeight = Math.max(80, startPosRef.current.height - deltaY);
        updates.height = newHeight;
        updates.y = startPosRef.current.groupY + (startPosRef.current.height - newHeight);
      }

      updateGroup(group.id, updates);
    };

    const handleMouseUp = () => {
      setIsResizing(false);
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
  }, [group.id, group.width, group.height, group.x, group.y, updateGroup]);

  // Handle context menu
  const handleContextMenu = useCallback((e) => {
    e.preventDefault();
    e.stopPropagation();
    
    showContextMenu(e.clientX, e.clientY, 'group', group.id, [
      {
        label: 'Rename',
        icon: <Edit2 size={14} />,
        action: () => {
          setIsEditing(true);
          setTimeout(() => inputRef.current?.focus(), 50);
        },
      },
      {
        label: 'Change Color',
        icon: <Palette size={14} />,
        action: () => {
          const colors = [
            'hsl(220, 70%, 85%)',
            'hsl(160, 70%, 85%)',
            'hsl(280, 70%, 85%)',
            'hsl(40, 70%, 85%)',
            'hsl(0, 70%, 85%)',
            'hsl(100, 70%, 85%)',
          ];
          const randomColor = colors[Math.floor(Math.random() * colors.length)];
          updateGroup(group.id, { color: randomColor });
        },
      },
      {
        label: 'Duplicate',
        icon: <Copy size={14} />,
        action: () => {
          useStore.getState().addGroup(group.x + 30, group.y + 30, group.parentId);
        },
      },
      { type: 'divider' },
      {
        label: 'Delete',
        icon: <Trash2 size={14} />,
        action: () => deleteGroup(group.id),
        danger: true,
      },
    ]);
  }, [group.id, group.x, group.y, group.parentId, showContextMenu, updateGroup, deleteGroup]);

  // Handle name edit
  const handleNameSubmit = useCallback(() => {
    updateGroup(group.id, { name });
    setIsEditing(false);
  }, [group.id, name, updateGroup]);

  const handleKeyDown = useCallback((e) => {
    if (e.key === 'Enter') {
      handleNameSubmit();
    } else if (e.key === 'Escape') {
      setName(group.name);
      setIsEditing(false);
    }
  }, [group.name, handleNameSubmit]);

  // Handle double-click to edit name
  const handleDoubleClick = useCallback((e) => {
    if (e.target.closest('.group-header')) {
      setIsEditing(true);
      setTimeout(() => inputRef.current?.focus(), 50);
    }
  }, []);

  return (
    <div
      className={`group-block ${selected ? 'selected' : ''} ${isResizing ? 'resizing' : ''}`}
      style={{
        left: group.x,
        top: group.y,
        width: group.width,
        height: group.height,
        backgroundColor: group.color,
        zIndex: selected ? 5 : 1, // Groups always at the back
      }}
      onMouseDown={handleMouseDown}
      onContextMenu={handleContextMenu}
      onDoubleClick={handleDoubleClick}
    >
      {/* Header */}
      <div className="group-header">
        {isEditing ? (
          <input
            ref={inputRef}
            type="text"
            className="group-name-input"
            value={name}
            onChange={(e) => setName(e.target.value)}
            onBlur={handleNameSubmit}
            onKeyDown={handleKeyDown}
            placeholder="Group name..."
          />
        ) : (
          <span className="group-name">
            {group.name || 'Unnamed Group'}
          </span>
        )}
      </div>

      {/* Content area (for nested elements) */}
      <div className="group-content">
        {/* Nested groups and items will render here via z-index */}
      </div>

      {/* Resize handles */}
      {selected && (
        <>
          <div className="resize-handle n" onMouseDown={(e) => handleResizeStart(e, 'n')} />
          <div className="resize-handle s" onMouseDown={(e) => handleResizeStart(e, 's')} />
          <div className="resize-handle e" onMouseDown={(e) => handleResizeStart(e, 'e')} />
          <div className="resize-handle w" onMouseDown={(e) => handleResizeStart(e, 'w')} />
          <div className="resize-handle ne" onMouseDown={(e) => handleResizeStart(e, 'ne')} />
          <div className="resize-handle nw" onMouseDown={(e) => handleResizeStart(e, 'nw')} />
          <div className="resize-handle se" onMouseDown={(e) => handleResizeStart(e, 'se')} />
          <div className="resize-handle sw" onMouseDown={(e) => handleResizeStart(e, 'sw')} />
        </>
      )}

      {/* Visual indicator for drop zone */}
      <div className="group-drop-indicator" />
    </div>
  );
};

export default GroupBlock;
