/**
 * Toolbar - Top toolbar with tools and actions
 */

import React from 'react';
import useStore from '../../store/useStore';
import { 
  MousePointer2, 
  Hand, 
  ArrowUpRight, 
  Table2, 
  Square, 
  Save, 
  Download,
  ZoomIn,
  ZoomOut,
  Maximize,
  Undo,
  Redo,
  HelpCircle,
} from 'lucide-react';
import './Toolbar.css';

const Toolbar = () => {
  const {
    activeTool,
    setActiveTool,
    canvas,
    setZoom,
    resetCanvas,
    saveToBackend,
    addGroup,
    addTimetable,
    classes,
  } = useStore();

  const tools = [
    { id: 'select', icon: MousePointer2, label: 'Select (V)', shortcut: 'V' },
    { id: 'pan', icon: Hand, label: 'Pan (H)', shortcut: 'H' },
    { id: 'arrow', icon: ArrowUpRight, label: 'Arrow (A)', shortcut: 'A' },
    { id: 'timetable', icon: Table2, label: 'Timetable (T)', shortcut: 'T' },
    { id: 'group', icon: Square, label: 'Group (G)', shortcut: 'G' },
  ];

  const handleToolClick = (toolId) => {
    if (toolId === 'group') {
      // Clicking group tool adds a group at center
      addGroup(0, 0);
      setActiveTool('select');
    } else if (toolId === 'timetable') {
      // Clicking timetable tool adds a timetable at center
      if (classes.length > 0) {
        addTimetable(100, 0, classes[0].id, null);
      }
      setActiveTool('select');
    } else {
      setActiveTool(toolId);
    }
  };

  const handleZoomIn = () => {
    setZoom(canvas.zoom * 1.2);
  };

  const handleZoomOut = () => {
    setZoom(canvas.zoom / 1.2);
  };

  const handleFitToScreen = () => {
    resetCanvas();
  };

  const handleSave = () => {
    saveToBackend();
  };

  return (
    <div className="toolbar">
      {/* Logo */}
      <div className="toolbar-brand">
        <span className="brand-icon">∞</span>
        <span className="brand-name">InfinityPane</span>
      </div>

      {/* Divider */}
      <div className="toolbar-divider" />

      {/* Main Tools */}
      <div className="toolbar-group tools-group">
        {tools.map((tool) => (
          <button
            key={tool.id}
            className={`toolbar-button ${activeTool === tool.id ? 'active' : ''}`}
            onClick={() => handleToolClick(tool.id)}
            title={tool.label}
          >
            <tool.icon size={18} />
          </button>
        ))}
      </div>

      {/* Divider */}
      <div className="toolbar-divider" />

      {/* Zoom Controls */}
      <div className="toolbar-group zoom-group">
        <button 
          className="toolbar-button"
          onClick={handleZoomOut}
          title="Zoom Out"
        >
          <ZoomOut size={18} />
        </button>
        <div className="zoom-display" onClick={handleFitToScreen} title="Click to reset">
          {Math.round(canvas.zoom * 100)}%
        </div>
        <button 
          className="toolbar-button"
          onClick={handleZoomIn}
          title="Zoom In"
        >
          <ZoomIn size={18} />
        </button>
        <button 
          className="toolbar-button"
          onClick={handleFitToScreen}
          title="Reset View (Ctrl+0)"
        >
          <Maximize size={18} />
        </button>
      </div>

      {/* Spacer */}
      <div className="toolbar-spacer" />

      {/* History Controls (placeholder) */}
      <div className="toolbar-group">
        <button className="toolbar-button disabled" title="Undo (Ctrl+Z)" disabled>
          <Undo size={18} />
        </button>
        <button className="toolbar-button disabled" title="Redo (Ctrl+Y)" disabled>
          <Redo size={18} />
        </button>
      </div>

      {/* Divider */}
      <div className="toolbar-divider" />

      {/* Actions */}
      <div className="toolbar-group">
        <button 
          className="toolbar-button"
          onClick={handleSave}
          title="Save (Ctrl+S)"
        >
          <Save size={18} />
        </button>
        <button className="toolbar-button" title="Export">
          <Download size={18} />
        </button>
      </div>

      {/* Divider */}
      <div className="toolbar-divider" />

      {/* Help */}
      <button className="toolbar-button" title="Help & Shortcuts">
        <HelpCircle size={18} />
      </button>
    </div>
  );
};

export default Toolbar;
